		return
	}

	fmt.Printf("✅ Loaded %d tokens from %d vocab\n\n", len(tokens), len(vocab))

	// 모델 생성
	fmt.Println("[2/5] Creating model with Adam...")
	lr := 0.001 // Adam의 권장 학습률
	model := NewSimpleModel(len(vocab), 64, lr)
	fmt.Printf("✅ Model created: vocab=%d, dModel=64, lr=%.4f\n\n", len(vocab), lr)

	// 학습 설정
	fmt.Println("[3/5] Training setup...")
	sequenceLen := 32
	batchSize := 64
	epochs := 20 // Priority 2 (5) → Priority 3 (20)

	numBatches := (len(tokens) - sequenceLen) / batchSize
	if numBatches > 500 {
		numBatches = 500
	}

	fmt.Printf("   Sequence length: %d\n", sequenceLen)
	fmt.Printf("   Batch size: %d\n", batchSize)
	fmt.Printf("   Batches per epoch: %d\n", numBatches)
	fmt.Printf("   Total epochs: %d\n", epochs)
	fmt.Printf("   Optimizer: Adam (β1=0.9, β2=0.999, ε=1e-8)\n\n", )

	// 학습 루프
	fmt.Println("[4/5] Training...")
	fmt.Println("════════════════════════════════════════════════════════")

	losses := make([]float64, 0)

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0
		batchCount := 0

		for batch := 0; batch < numBatches; batch++ {
			// 랜덤 위치에서 시퀀스 샘플
