	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🎯 Training Complete!")
	fmt.Println("════════════════════════════════════════════════════════\n")

	fmt.Println("📊 Loss Trajectory (Selected Epochs):")
	step := len(losses) / 10
	if step < 1 {
		step = 1
	}
	for i := 0; i < len(losses); i += step {
		loss := losses[i]
		ppl := math.Exp(loss)
		bar := ""
		barLen := int((losses[0] - loss) / losses[0] * 40)
		if barLen > 40 {
			barLen = 40
		}
		if barLen < 0 {
			barLen = 0
		}
		for j := 0; j < barLen; j++ {
