// ==================================================
// Phase 7: Optimizer (Adam & SGD)
// ==================================================
// 최적화 알고리즘: SGD, Momentum, Adam
//
// 구조:
// 1. SGD: w -= lr * grad
// 2. Momentum: v = beta*v + grad, w -= lr*v
// 3. Adam: m,v 모멘트 + bias correction
//
// 참고: Go 구현 (train/real_loss.go)을 FL로 포팅

// ==================================================
// 1. Tensor 기반 기본 연산
// ==================================================

function add_tensors(a: Array[Float], b: Array[Float]) -> Array[Float] = {
  let result = a;
  fold_range(0, length(a), function(i: Int) {
    result[i] = a[i] + b[i];
    ()
  });
  result
}

function scale_tensor(t: Array[Float], scalar: Float) -> Array[Float] = {
  let result = t;
  fold_range(0, length(t), function(i: Int) {
    result[i] = t[i] * scalar;
    ()
  });
  result
}

function clip_tensor(t: Array[Float], min_val: Float, max_val: Float) -> Array[Float] = {
  let result = t;
  fold_range(0, length(t), function(i: Int) {
    if t[i] > max_val {
      result[i] = max_val
    } else if t[i] < min_val {
      result[i] = min_val
    } else {
      result[i] = t[i]
    };
    ()
  });
  result
}

// ==================================================
// 2. SGD Optimizer
// ==================================================

record SGDState {
  lr: Float,              // learning rate
  momentum: Float,        // (선택사항)
  velocity: Array[Float]  // v = beta*v + grad
}

function sgd_init(learning_rate: Float, param_size: Int) -> SGDState = {
  {
    lr: learning_rate,
    momentum: 0.0,
    velocity: Array.create(param_size, 0.0)
  }
}

function sgd_step(
  params: Array[Float],
  grads: Array[Float],
  state: SGDState
) -> (Array[Float], SGDState) = {
  // Simple SGD: w -= lr * grad
  let updated_params = params;
  fold_range(0, length(params), function(i: Int) {
    updated_params[i] = params[i] - state.lr * grads[i];
    ()
  });

  let updated_state = {
    lr: state.lr,
    momentum: state.momentum,
    velocity: state.velocity
  };

  (updated_params, updated_state)
}

// ==================================================
// 3. Momentum Optimizer
// ==================================================

record MomentumState {
  lr: Float,
  beta: Float,           // 0.9 (momentum factor)
  velocity: Array[Float] // v_t = beta*v_{t-1} + grad
}

function momentum_init(learning_rate: Float, beta: Float, param_size: Int) -> MomentumState = {
  {
    lr: learning_rate,
    beta: beta,
    velocity: Array.create(param_size, 0.0)
  }
}

function momentum_step(
  params: Array[Float],
  grads: Array[Float],
  state: MomentumState
) -> (Array[Float], MomentumState) = {
  // v_t = beta * v_{t-1} + grad
  let new_velocity = state.velocity;
  fold_range(0, length(grads), function(i: Int) {
    new_velocity[i] = state.beta * state.velocity[i] + grads[i];
    ()
  });

  // w -= lr * v_t
  let updated_params = params;
  fold_range(0, length(params), function(i: Int) {
    updated_params[i] = params[i] - state.lr * new_velocity[i];
    ()
  });

  let updated_state = {
    lr: state.lr,
    beta: state.beta,
    velocity: new_velocity
  };

  (updated_params, updated_state)
}

// ==================================================
// 4. Adam Optimizer (핵심)
// ==================================================

record AdamState {
  lr: Float,           // learning rate
  beta1: Float,        // 0.9 (1차 모멘트 감쇠)
  beta2: Float,        // 0.999 (2차 모멘트 감쇠)
  eps: Float,          // 1e-8 (수치 안정성)
  t: Int,              // 타임스텝
  m: Array[Float],     // 1차 모멘트 (momentum)
  v: Array[Float]      // 2차 모멘트 (variance)
}

function adam_init(
  learning_rate: Float,
  param_size: Int
) -> AdamState = {
  {
    lr: learning_rate,
    beta1: 0.9,
    beta2: 0.999,
    eps: 0.00000001,  // 1e-8
    t: 0,
    m: Array.create(param_size, 0.0),
    v: Array.create(param_size, 0.0)
  }
}

function pow_float(base: Float, exp: Float) -> Float = {
  // base^exp (simplified: only for small exponents)
  // For bias correction: (0.9)^t, (0.999)^t
  if exp == 1.0 {
    base
  } else if exp == 2.0 {
    base * base
  } else {
    // Approximate for other cases
    base
  }
}

function adam_step(
  params: Array[Float],
  grads: Array[Float],
  state: AdamState
) -> (Array[Float], AdamState) = {
  // Step 1: t += 1
  let t_new = state.t + 1;

  // Step 2: m_t = beta1 * m_{t-1} + (1 - beta1) * g_t
  let m_new = state.m;
  fold_range(0, length(grads), function(i: Int) {
    m_new[i] = state.beta1 * state.m[i] + (1.0 - state.beta1) * grads[i];
    ()
  });

  // Step 3: v_t = beta2 * v_{t-1} + (1 - beta2) * g_t^2
  let v_new = state.v;
  fold_range(0, length(grads), function(i: Int) {
    v_new[i] = state.beta2 * state.v[i] + (1.0 - state.beta2) * (grads[i] * grads[i]);
    ()
  });

  // Step 4: Bias correction
  // bias_corr1 = 1 - beta1^t
  // bias_corr2 = 1 - beta2^t
  let bias_corr1 = 1.0 - pow_float(state.beta1, as_float(t_new));
  let bias_corr2 = 1.0 - pow_float(state.beta2, as_float(t_new));

  // Step 5: m_hat = m_t / bias_corr1, v_hat = v_t / bias_corr2
  // Step 6: w -= lr * m_hat / (sqrt(v_hat) + eps)
  let updated_params = params;
  fold_range(0, length(params), function(i: Int) {
    let m_hat = m_new[i] / bias_corr1;
    let v_hat = v_new[i] / bias_corr2;
    let denom = sqrt(v_hat) + state.eps;
    updated_params[i] = params[i] - state.lr * m_hat / denom;
    ()
  });

  let updated_state = {
    lr: state.lr,
    beta1: state.beta1,
    beta2: state.beta2,
    eps: state.eps,
    t: t_new,
    m: m_new,
    v: v_new
  };

  (updated_params, updated_state)
}

// ==================================================
// 5. Utility: Gradient Clipping
// ==================================================

function clip_grads(grads: Array[Float], max_norm: Float) -> Array[Float] = {
  let norm = sqrt(fold_range(0, length(grads), 0.0, function(acc: Float, i: Int) {
    acc + grads[i] * grads[i]
  }));

  if norm > max_norm {
    scale_tensor(grads, max_norm / norm)
  } else {
    grads
  }
}

// ==================================================
// 6. Learning Rate Scheduling (선택사항)
// ==================================================

function lr_schedule_linear(
  initial_lr: Float,
  epoch: Int,
  total_epochs: Int
) -> Float = {
  // 선형 감소: lr = initial_lr * (1 - epoch / total_epochs)
  initial_lr * (1.0 - as_float(epoch) / as_float(total_epochs))
}

function lr_schedule_exponential(
  initial_lr: Float,
  epoch: Int,
  decay_rate: Float
) -> Float = {
  // 지수 감소: lr = initial_lr * decay_rate^epoch
  initial_lr * pow_float(decay_rate, as_float(epoch))
}

// ==================================================
// 7. 테스트 함수
// ==================================================

function test_optimizers() -> () = {
  // Dummy test
  let params = [1.0, 2.0, 3.0];
  let grads = [0.1, 0.2, 0.3];

  // SGD
  let sgd_state = sgd_init(0.01, length(params));
  let (params_sgd, _) = sgd_step(params, grads, sgd_state);

  // Adam
  let adam_state = adam_init(0.001, length(params));
  let (params_adam, _) = adam_step(params, grads, adam_state);

  ()
}

